90	/// POST /api/privacy/signup - Register with email and send magic link
91	pub async fn signup(
92	    Extension(state): Extension<Arc<AppState>>,
93	    Json(request): Json<SignupRequest>,
94	) -> (StatusCode, Json<SignupResponse>) {
95	    let email = request.email.trim().to_lowercase();
96	
97	    // 1. Basic Rate Limiting: Prevent magic link spam
98	    // In production, use Redis or a proper rate limiting crate.
99	    {
100	        // Add a simple in-memory signup rate tracker to AppState if needed,
101	        // but for now, we'll check magic_links map for existing tokens
102	        // or add a simple static rate limiter for this prototype.
103	        static LAST_SIGNUP: tokio::sync::Mutex<
104	            Option<std::collections::HashMap<String, std::time::Instant>>,
105	        > = tokio::sync::Mutex::const_new(None);
106	
107	        let mut map_guard = LAST_SIGNUP.lock().await;
108	        if map_guard.is_none() {
109	            *map_guard = Some(std::collections::HashMap::new());
110	        }
111	
112	        if let Some(ref mut map) = *map_guard {
113	            if let Some(last_time) = map.get(&email) {
114	                if last_time.elapsed().as_secs() < 60 {
115	                    return (
116	                        StatusCode::TOO_MANY_REQUESTS,
117	                        Json(SignupResponse {
118	                            success: false,
119	                            message: "Please wait 60 seconds before requesting another login link"
120	                                .to_string(),
121	                        }),
122	                    );
123	                }
124	            }
125	            map.insert(email.clone(), std::time::Instant::now());
126	
127	            // Periodically clean up old entries
128	            if map.len() > 1000 {
129	                map.retain(|_, v| v.elapsed().as_secs() < 3600);
130	            }
131	        }
132	    }
133	
134	    // Basic email validation
135	    if !email.contains('@') || !email.contains('.') {
136	        return (
137	            StatusCode::BAD_REQUEST,
138	            Json(SignupResponse {
139	                success: false,
140	                message: "Invalid email address".to_string(),
141	            }),
142	        );
143	    }
144	
145	    // Check if user already exists
