# /etc/nginx/http.d/assistant-3tched.com
# assistant.3tched.com - Axon Trace UI via WireGuard zero-trust
#
# Serves the axon-trace-ui React SPA built from ui/axon-trace-ui/
# and proxies gRPC-Web calls to the wg-xray container bridge.
#
# ACCESS: WireGuard tunnel only. Public internet receives 404.
#
# Build the UI before deploying:
#   cd ui/axon-trace-ui && npm ci && npm run build
#   sudo cp -r dist/* /var/www/assistant/
#
# Requires:
#   - SSL cert at /etc/letsencrypt/live/3tched.com/
#   - Static files in /var/www/assistant/
#   - op-grpc-bridge running at 10.200.0.2:50051 (wg-xray container)

# ── Public internet: deny all ──
server {
    listen 148.113.204.83:80;
    server_name assistant.3tched.com;
    return 404;
}

server {
    listen 148.113.204.83:443 ssl;
    http2 on;
    server_name assistant.3tched.com;

    ssl_certificate /etc/letsencrypt/live/3tched.com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/3tched.com/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;

    return 404;
}

# ── WireGuard tunnel: serve UI + proxy gRPC ──
server {
    listen 10.0.0.1:80;
    server_name assistant.3tched.com;

    location / {
        return 301 https://$host$request_uri;
    }
}

server {
    listen 10.0.0.1:443 ssl;
    http2 on;
    server_name assistant.3tched.com;

    ssl_certificate /etc/letsencrypt/live/3tched.com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/3tched.com/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;

    # Security headers
    add_header X-Frame-Options "SAMEORIGIN" always;
    add_header X-Content-Type-Options "nosniff" always;
    add_header Referrer-Policy "strict-origin-when-cross-origin" always;

    # CORS for assistant.3tched.com
    add_header Access-Control-Allow-Origin "https://assistant.3tched.com" always;
    add_header Access-Control-Allow-Methods "GET, POST, PUT, DELETE, OPTIONS" always;
    add_header Access-Control-Allow-Headers "Authorization, Content-Type, X-API-Key, X-WireGuard-Pubkey, X-Ghostbridge-Footprint, X-Ghostbridge-Trace-ID" always;

    # Handle preflight
    if ($request_method = OPTIONS) {
        return 204;
    }

    # ── gRPC-Web: proxy to wg-xray op-grpc-bridge ──
    location ~ ^/operation\.v1\.[^/]+/[^/]+$ {
        proxy_pass http://10.200.0.2:50051;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header X-Forwarded-Host $host;
        proxy_set_header TE $http_te;
        proxy_set_header Connection "TE";
        proxy_buffering off;
        proxy_request_buffering off;
        proxy_read_timeout 86400s;
        proxy_send_timeout 86400s;
    }

    # ── gRPC health check ──
    location = /grpc.health.v1.Health/Check {
        proxy_pass http://10.200.0.2:50051;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header X-Forwarded-Host $host;
        proxy_set_header TE $http_te;
        proxy_set_header Connection "TE";
        proxy_buffering off;
        proxy_request_buffering off;
        proxy_read_timeout 60s;
        proxy_send_timeout 60s;
    }

    # ── D-Bus passthrough (operation.v1.DbusPassthrough) ──
    location ~ ^/operation\.v1\.DbusPassthrough/ {
        proxy_pass http://10.200.0.2:50051;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_buffering off;
        proxy_read_timeout 300s;
    }

    # ── Assistant gRPC (ai.assistant.v1) ──
    # These are also handled by the gRPC bridge (D-Bus passthrough internally)
    location ~ ^/ai\.assistant\.v1\.[^/]+/[^/]+$ {
        proxy_pass http://10.200.0.2:50051;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header X-Forwarded-Host $host;
        proxy_set_header TE $http_te;
        proxy_set_header Connection "TE";
        proxy_buffering off;
        proxy_request_buffering off;
        proxy_read_timeout 86400s;
        proxy_send_timeout 86400s;
    }

    # ── op-assistant-grpc direct (if needed) ──
    location ~ ^/assistant\.v1\.[^/]+/[^/]+$ {
        proxy_pass http://127.0.0.1:50052;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header X-Forwarded-Host $host;
        proxy_set_header TE $http_te;
        proxy_set_header Connection "TE";
        proxy_buffering off;
        proxy_request_buffering off;
        proxy_read_timeout 86400s;
        proxy_send_timeout 86400s;
    }

    # ── Static SPA: axon-trace-ui ──
    location / {
        root /var/www/assistant;
        index index.html;
        try_files $uri $uri/ /index.html;

        # Cache static assets
        location ~* \.(js|css|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot)$ {
            expires 1y;
            add_header Cache-Control "public, immutable";
        }
    }

    access_log /var/log/nginx/assistant.3tched.com.access.log;
    error_log /var/log/nginx/assistant.3tched.com.error.log;
}

