189	    let unix_listener = tokio::net::UnixListener::bind(&unix_socket)?;
190	    info!(path = %unix_socket.display(), "zeroclaw native gRPC listening on Unix socket");
191	
192	    let unix_incoming = tokio_stream::wrappers::UnixListenerStream::new(unix_listener);
193	
194	    let tonic_server = tonic::transport::Server::builder()
195	        .add_routes(build_tonic_routes(loader.clone()))
196	        .serve_with_incoming(unix_incoming);
