100	    /// Read this plugin's desired socket set straight from the single active
101	    /// schema catalog in shared memory (zero-copy 1:1). The catalog is keyed by
102	    /// plugin name and each entry carries the schema-declared state.
103	    fn read_desired() -> UnixSocketState {
104	        let Ok(mut bytes) = std::fs::read(SHM_SCHEMA_PATH) else {
105	            return UnixSocketState::default();
106	        };
107	        let Ok(catalog) = simd_json::to_owned_value(&mut bytes) else {
108	            return UnixSocketState::default();
109	        };
110	        let Some(state) = catalog
111	            .get("unix_socket")
112	            .and_then(|versions| versions.as_array())
113	            .and_then(|versions| versions.last())
114	            .and_then(|schema| schema.get("example"))
115	        else {
116	            return UnixSocketState::default();
117	        };
118	        simd_json::serde::from_owned_value::<UnixSocketState>(state.clone()).unwrap_or_default()
119	    }
