121	    /// Bind a single endpoint, replacing any stale socket file. Returns `true`
122	    /// when a new listener was created.
123	    fn ensure_bound(
124	        active: &mut HashMap<String, UnixListener>,
125	        endpoint: &SocketEndpoint,
126	    ) -> Result<bool> {
127	        if active.contains_key(&endpoint.path) {
128	            return Ok(false);
129	        }
130	        if let Some(parent) = Path::new(&endpoint.path).parent() {
131	            std::fs::create_dir_all(parent)?;
132	        }
133	        if Path::new(&endpoint.path).exists() {
134	            std::fs::remove_file(&endpoint.path)?;
135	        }
136	        let listener = UnixListener::bind(&endpoint.path)?;
137	        listener.set_nonblocking(true)?;
138	        active.insert(endpoint.path.clone(), listener);
139	        info!(
140	            socket = %endpoint.path,
141	            port = endpoint.port,
142	            protocol = %endpoint.protocol,
143	            "bound unix socket endpoint"
144	        );
145	        Ok(true)
146	    }
147	
148	    /// Drop a listener and unlink its socket file. Returns `true` when removed.
149	    fn unbind(active: &mut HashMap<String, UnixListener>, path: &str) -> bool {
150	        if active.remove(path).is_some() {
151	            if let Err(error) = std::fs::remove_file(path) {
152	                warn!(socket = %path, %error, "failed to unlink unix socket file");
153	            }
154	            true
155	        } else {
156	            false
157	        }
158	    }
