160	    /// Reconcile the live listeners to exactly the supplied desired set.
161	    fn reconcile(&self, desired: &UnixSocketState) -> ApplyResult {
162	        let mut active = self.active.lock();
163	        let mut changes_applied = Vec::new();
164	        let mut errors = Vec::new();
165	
166	        let wanted: HashSet<String> = desired.sockets.iter().map(|s| s.path.clone()).collect();
167	
168	        for endpoint in &desired.sockets {
169	            match Self::ensure_bound(&mut active, endpoint) {
170	                Ok(true) => changes_applied.push(format!(
171	                    "created socket {} (port {}, {})",
172	                    endpoint.path, endpoint.port, endpoint.protocol
173	                )),
174	                Ok(false) => {}
175	                Err(error) => errors.push(format!(
176	                    "failed to create socket {}: {}",
177	                    endpoint.path, error
178	                )),
179	            }
180	        }
181	
182	        let stale: Vec<String> = active
183	            .keys()
184	            .filter(|path| !wanted.contains(*path))
185	            .cloned()
186	            .collect();
187	        for path in stale {
188	            if Self::unbind(&mut active, &path) {
189	                changes_applied.push(format!("removed socket {}", path));
190	            }
191	        }
192	
193	        ApplyResult {
194	            success: errors.is_empty(),
195	            changes_applied,
196	            errors,
197	            checkpoint: None,
198	        }
199	    }
200	}
