28	export function SchemaForm({
29	  schema,
30	  value,
31	  onChange,
32	  onSubmit,
33	  className,
34	  disabled = false,
35	}: SchemaFormProps) {
36	  const [errors, setErrors] = useState<Record<string, string>>({});
37	
38	  const validateField = useCallback((key: string, prop: SchemaProperty, val: unknown): string | null => {
39	    if (prop.minLength && typeof val === "string" && val.length < prop.minLength) {
40	      return `Minimum length is ${prop.minLength}`;
41	    }
42	    if (schema?.required?.includes(key) && (!val || (typeof val === "string" && val.trim() === ""))) {
43	      return "This field is required";
44	    }
45	    return null;
46	  }, [schema?.required]);
47	
48	  const handleFieldChange = (key: string, prop: SchemaProperty, newValue: unknown) => {
49	    const error = validateField(key, prop, newValue);
50	    setErrors((prev) => ({ ...prev, [key]: error || "" }));
51	    onChange({ ...value, [key]: newValue });
52	  };
53	
54	  const handleKeyDown = (e: React.KeyboardEvent) => {
55	    if (e.key === "Enter" && !e.shiftKey) {
56	      e.preventDefault();
57	      onSubmit();
58	    }
59	  };
60	
61	  if (!schema || schema.type !== "object" || !schema.properties) {
62	    return (
63	      <div className={cn("text-sm text-muted-foreground", className)}>
64	        No schema available
65	      </div>
66	    );
67	  }
68	
69	  const properties = schema.properties;
70	
71	  return (
72	    <div className={cn("space-y-4", className)}>
73	      {Object.entries(properties).map(([key, prop]) => (
74	        <SchemaField
75	          key={key}
76	          name={key}
77	          property={prop}
78	          value={value[key]}
79	          error={errors[key]}
80	          required={schema.required?.includes(key)}
81	          disabled={disabled}
82	          onChange={(newValue) => handleFieldChange(key, prop, newValue)}
83	          onKeyDown={handleKeyDown}
84	        />
85	      ))}
86	    </div>
87	  );
88	}
89	
