91	  name: string;
92	  property: SchemaProperty;
93	  value: unknown;
94	  error?: string;
95	  required?: boolean;
96	  disabled?: boolean;
97	  onChange: (value: unknown) => void;
98	  onKeyDown: (e: React.KeyboardEvent) => void;
