135	            </option>
136	          ))}
137	        </select>
138	        {error && <span className="text-xs text-danger">{error}</span>}
139	      </div>
140	    );
141	  }
142	
143	  // oneOf select with const/title (model dropdown)
144	  if (property.oneOf && property.oneOf.length > 0) {
145	    return (
146	      <div className="space-y-1">
147	        <label className="text-xs font-medium text-muted-foreground uppercase tracking-wider">
